package A4;
import java.io.*;import java.util.*;
public class Hostel implements Serializable{private static final long serialVersionUID=1L;private final List<Room>rooms=new ArrayList<>();public void addRoom(Room r){rooms.add(r);}public List<Room>rooms(){return Collections.unmodifiableList(rooms);}public static class Room implements Serializable{private static final long serialVersionUID=1L;private final String roomNo;private final List<Resident>residents=new ArrayList<>();public Room(String n){roomNo=n;}public void add(Resident r){residents.add(r);}}public static class Resident implements Serializable{private static final long serialVersionUID=1L;private final String name,regNo;private final String phone;private transient String password;private transient Object liveConnection;public Resident(String n,String id,String phone,String pwd){name=n;regNo=id;this.phone=phone;password=pwd;}}}
